import { type LineSvgProps, ResponsiveLine as Line } from "@harbor-charts/line";
import { ResponsivePie as Pie } from "@harbor-charts/pie";
import {
	Component,
	Element,
	Fragment,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";
import * as React from "react";
import { createRoot } from "react-dom/client";
import {
	type ChartBoardType,
	type IllustrationSize,
	createBoardController,
	hasAssignedEmptyState,
	hasAssignedLoadingState,
	hideBothEmptyRefs,
	showNativeEmptyRef,
	showReactEmptyRef,
} from "./board-util";
import {
	emptyConfigForBarline,
	emptyConfigForDonut,
	emptyInnerHtmlForPie,
} from "./configs";

/**
 * @since 1.0.50
 * @status stable
 */
@Component({
	tag: "hbr-chart-board",
	styleUrl: "style.scss",
	shadow: true,
})
export class HbrChartBoard {
	@Element() private el: HTMLHbrChartBoardElement;

	loadingRef: HTMLElement;
	emptyRootRef: HTMLElement;
	emptyNativeRef: HTMLElement;

	private resizeObserver!: ResizeObserver;

	private contextRoot: ReturnType<typeof createRoot> | null = null;

	/** Show loading state */
	@Prop({ reflect: true })
	isLoading = false;

	/** Chart type for empty state illustration */
	@Prop({ reflect: true })
	type: ChartBoardType = "none";

	/** Show empty state */
	@Prop()
	isEmpty = false;

	/** Description for empty state */
	@Prop()
	description = "No data to display";

	@State()
	config = {
		margin: {
			right: 0,
			bottom: 0,
			left: 0,
			top: 0,
		},
	};

	@State()
	illustrationSize: IllustrationSize = "large";

	@Method()
	async setChartConfig(config) {
		this.config = config;
	}

	// controller to manage empty/loading states
	// With ResizeObserver, controller can adjust illustration size based on container size
	// and also debounce resize events to avoid excessive re-renders
	private controller = createBoardController({
		getEl: () => this.el as HTMLElement,

		getIsLoading: () => this.isLoading,
		getIsEmpty: () => this.isEmpty,
		getType: () => this.type,
		getDescription: () => this.description,

		hasEmptyRefs: () => !!this.emptyRootRef && !!this.emptyNativeRef,

		updateIllustrationSize: (next) => {
			if (next !== this.illustrationSize) this.illustrationSize = next;
		},

		toggleVisibilityOnBarLineEmpty: (visible) => {
			if (this.emptyRootRef) {
				this.emptyRootRef.style.display = visible ? "block" : "none";
			}
		},

		renderDefaultEmptyBg: (w, h, v) => this.renderDefaultEmptyBg(w, h, v),

		debounceMs: 80,
	});

	componentDidLoad() {
		this.resizeObserver = new ResizeObserver((entries) => {
			for (const entry of entries) {
				const { width, height } = entry.contentRect;
				this.controller.onResize(width, height);
			}
		});
		this.resizeObserver.observe(this.el);
	}

	disconnectedCallback() {
		this.controller.disconnect();

		if (this.contextRoot) {
			this.contextRoot.unmount();
			this.contextRoot = null;
		}

		this.resizeObserver?.disconnect();
	}

	@Watch("type")
	@Watch("description")
	@Watch("isEmpty")
	@Watch("isLoading")
	onPropsAffectingEmptyChange() {
		// When leaving the empty state, clear imperatively-set content on refs
		// before Stencil re-renders — its VDOM diff may reuse these DOM nodes
		// for the non-empty branch (e.g. emptyNativeRef → footer div),
		// and text set via .textContent would otherwise persist.
		if (!this.isEmpty) {
			if (this.emptyNativeRef) {
				this.emptyNativeRef.textContent = "";
			}
			if (this.contextRoot) {
				this.contextRoot.unmount();
				this.contextRoot = null;
			}
		}
		this.controller.onPropAffectsEmptyChanged();
	}

	private renderDefaultEmptyBg(
		width: number,
		height: number,
		visibility: boolean,
	) {
		let emptyEntity: React.ReactElement | null = null;

		if (this.type === "categorical") {
			showNativeEmptyRef(this.emptyNativeRef, this.emptyRootRef);
			this.emptyNativeRef.textContent = this.description;
			return;
		}

		if (this.type === "gauge") {
			showNativeEmptyRef(this.emptyNativeRef, this.emptyRootRef);
			this.emptyNativeRef.textContent = this.description;
			return;
		}

		if (this.type === "bar" || this.type === "line") {
			if (!visibility) {
				hideBothEmptyRefs(this.emptyNativeRef, this.emptyRootRef);
				return;
			}
			showReactEmptyRef(this.emptyNativeRef, this.emptyRootRef);
			emptyEntity = React.createElement(
				Line,
				emptyConfigForBarline() as LineSvgProps,
				null,
			);
		} else if (this.type === "donut") {
			showReactEmptyRef(this.emptyNativeRef, this.emptyRootRef);
			emptyEntity = React.createElement(Pie, emptyConfigForDonut(), null);
		} else if (this.type === "pie") {
			showNativeEmptyRef(this.emptyNativeRef, this.emptyRootRef);
			// 0.75 to maintain 4:3 aspect ratio
			// same as style.scss 75% width and height
			this.emptyNativeRef.innerHTML = emptyInnerHtmlForPie(
				width > 0 ? width * 0.75 : 400,
				height > 0 ? height * 0.75 : 300,
			);
			return;
		}

		if (
			(this.type === "bar" || this.type === "line" || this.type === "donut") &&
			emptyEntity
		) {
			if (!this.contextRoot) this.contextRoot = createRoot(this.emptyRootRef);
			this.contextRoot.render(
				React.createElement(React.Fragment, null, emptyEntity),
			);
		}
	}

	componentDidRender() {
		this.controller.renderEmptyIfNeeded();
	}

	render() {
		const customLoadingState = hasAssignedLoadingState(this.el);
		const customEmptyState = hasAssignedEmptyState(this.el);
		const { right = 0, left = 0 } = this.config?.margin || {};

		if (this.isLoading) {
			return (
				<Host>
					{customLoadingState ? (
						<slot name="loading-state" />
					) : (
						<div class="chart-board__loading">
							<hbr-stencil variant="chart" part="loading-state-illustration" />
							<div
								ref={(el) => {
									this.loadingRef = el;
								}}
								part="loading-state-image"
							/>
						</div>
					)}
				</Host>
			);
		}

		if (!this.isEmpty) {
			return (
				<Host>
					<Fragment>
						<div class="chart-board__container">
							<slot name="header" />
							<slot />
							{this.type === "categorical" && <slot name="legend" />}
							<div
								class="chart-board__footer"
								style={{
									marginLeft: `${left}px`,
									marginRight: `${right}px`,
								}}
							>
								<slot name="footer" />
							</div>
						</div>
					</Fragment>
				</Host>
			);
		}

		return (
			<Host>
				{customEmptyState ? (
					<slot name="empty-state" />
				) : (
					<div class={`chart-board__empty ${this.type}`}>
						{this.type !== "categorical" && this.type !== "gauge" && (
							<hbr-illustration
								size={this.illustrationSize}
								part="empty-state-illustration"
							>
								<div slot="body">{this.description}</div>
							</hbr-illustration>
						)}
						<div
							ref={(el) => {
								this.emptyRootRef = el;
							}}
							part="empty-state-image"
						/>
						<div
							ref={(el) => {
								this.emptyNativeRef = el;
							}}
							part="empty-state-image"
						/>
					</div>
				)}
			</Host>
		);
	}
}
