import {
	Component,
	Element,
	Event,
	type EventEmitter,
	Host,
	Method,
	Prop,
	State,
	Watch,
	h,
} from "@stencil/core";

import { isSafari } from "../../utils/browser";

import { parseDuration } from "../../utils/animate";
// TODO: animations
// import { animateTo, parseDuration, stopAnimations } from '../../utils/animate';
// import { getAnimation } from '../../utils/animate.js';

/**
 * @since 1.0.29
 * @status stable
 *
 * @slot - The popover's target element. Avoid slotting in more than one element, as subsequent ones will be ignored.
 * @slot content - The content to render in the popover. Alternatively, you can use the `content` attribute.
 *
 * @part base - The component's base wrapper, an `<hbr-popup>` element.
 * @part base__popup - The popup's exported `popup` part. Use this to target the popover's popup container.
 * @part base__arrow - The popup's exported `arrow` part. Use this to target the popover's arrow.
 * @part body - The popover's body where its content is rendered.
 *
 * @animation popover.show - The animation to use when showing the popover.
 * @animation popover.hide - The animation to use when hiding the popover.
 */

@Component({
	tag: "hbr-popover",
	styleUrl: "popover.scss",
	shadow: true,
})
export class HbrPopover {
	private hoverTimeout: number;
	private popupRef: HTMLHbrPopupElement;
	private popupContentRef: HTMLDivElement;
	private anchorRef: HTMLElement | SVGElement;
	private cancelHide = false;

	@Element() host!: HTMLHbrPopoverElement;

	/**
	 * The element the popup will be anchored to. If the anchor is external, you can provide a reference to an element or CSS selector via this prop. If the anchor lives inside the popover, donot pass this prop
	 * @deprecated Use `enable-popover` instead to avoid external anchors and portal usage.
	 */
	@Prop() anchor: HTMLElement | SVGElement | string;

	/** The popover's content. If you need to display HTML, use the `content` slot instead. */
	@Prop() content = "";

	/**
	 * The preferred placement of the popover. Note that the actual placement may vary as needed to keep the popover
	 * inside of the viewport.
	 */
	@Prop() placement:
		| "top"
		| "top-start"
		| "top-end"
		| "right"
		| "right-start"
		| "right-end"
		| "bottom"
		| "bottom-start"
		| "bottom-end"
		| "left"
		| "left-start"
		| "left-end" = "top";

	/** Disables the popover so it won't show when triggered. */
	@Prop({ reflect: true }) disabled = false;

	/** The distance in pixels from which to offset the popover away from its target. */
	@Prop() distance = 8;

	/** Indicates whether or not the popover is open. You can use this in lieu of the show/hide methods. */
	@Prop({ mutable: true, reflect: true }) open = false;

	/** The distance in pixels from which to offset the popover along its target. */
	@Prop() skidding = 0;

	/**
	 * Controls how the popover is activated. Possible options include `click`, `hover`, `focus`, and `manual`. Multiple
	 * options can be passed by separating them with a space. When manual is used, the popover must be activated
	 * programmatically.
	 */
	@Prop() trigger = "click";

	/**
	 * Enable this option to prevent the popover from being clipped when the component is placed inside a container with
	 * `overflow: auto|hidden|scroll`. Hoisting uses a fixed positioning strategy that works in many, but not all,
	 * scenarios.
	 */
	@Prop({ reflect: true }) hoist = false;

	/** Enable the native popover feature so that the popover layers above clipping containers. @version: 2.18.41 */
	@Prop() enablePopover = false;

	/**
	 * sizes correspond to max-width of popover
	 */
	@Prop() size: "small" | "medium" | "large";

	/**
	 * Use confirm variant for popconfirm styles, chart variant for chart/ dataviz popovers
	 */
	@Prop() variant: "default" | "confirm" | "chart" | "map" = "default";

	/** Supports brand sentiment for feature highlight popover */
	@Prop({ reflect: true }) sentiment: "brand";

	/** set min-width to max-width available for that size even if content is shorter, and max-width unbounded */
	@Prop({ reflect: true }) widthExpand = false;

	@State() featureHighlight = false;

	/** Emitted when the popover begins to show. */
	@Event({ eventName: "hbr-show" }) hbrShow: EventEmitter;

	/** Emitted after the popover has shown and all animations are complete. */
	@Event({ eventName: "hbr-after-show" }) hbrAfterShow: EventEmitter;

	/** Emitted when the popover begins to hide. */
	@Event({ eventName: "hbr-hide" }) hbrHide: EventEmitter;

	/** Emitted after the popover has hidden and all animations are complete. */
	@Event({ eventName: "hbr-after-hide" }) hbrAfterHide: EventEmitter;

	/** Emitted when body is clicked. Calling `event.preventDefault()` will prevent the popover from closing. */
	@Event({ eventName: "hbr-dismiss" }) hbrDismiss: EventEmitter;

	@Watch("open")
	async handleOpenChange() {
		if (!this.popupRef) return;
		if (this.open) {
			if (this.disabled) {
				return;
			}

			// Show
			this.hbrShow.emit();

			// TODO: animation
			/**  await stopAnimations(this.popupContentRef); */
			if (this.popupContentRef) {
				this.popupContentRef.hidden = false;
			}

			this.popupRef.active = true;
			/** 
      const { keyframes, options } = getAnimation(this.host, 'popover.show', { dir: "ltr" });
      await animateTo(this.popupRef.popupRef, keyframes, options);
      */
			this.hbrAfterShow.emit();
			// Dismiss on click outside
			document.addEventListener("click", this.handleBodyClick);
		} else {
			// Hide
			this.hbrHide.emit();

			// TODO: animation
			/** 
      await stopAnimations(this.popupContentRef);
      const { keyframes, options } = getAnimation(this, 'popover.hide', { dir: this.localize.dir() });
      await animateTo(this.popupRef.popupRef, keyframes, options);
      */
			this.popupRef.active = false;
			if (this.popupContentRef) {
				this.popupContentRef.hidden = true;
			}

			// Safari fix: force re-render of shadow DOM slot content
			if (isSafari()) {
				const anchor = this.anchorRef;
				if (anchor) {
					const parent = anchor.parentElement;
					const next = anchor.nextSibling;

					// Delay re-insertion slightly to ensure reflow
					requestAnimationFrame(() => {
						parent?.removeChild(anchor);
						requestAnimationFrame(() => {
							if (next) {
								parent?.insertBefore(anchor, next);
							} else {
								parent?.appendChild(anchor);
							}
						});
					});
				}
			}

			this.hbrAfterHide.emit();
			// Remove Dismiss on click outside
			// TODO: remove event doesn't work in portal case, probably because handleBodyClick reference changes
			document.removeEventListener("click", this.handleBodyClick);
		}
	}

	@Watch("content")
	@Watch("distance")
	@Watch("hoist")
	@Watch("placement")
	@Watch("skidding")
	async handleOptionsChange() {
		await this.popupRef?.reposition();
	}

	@Watch("disabled")
	handleDisabledChange() {
		if (this.disabled && this.open) {
			this.open = false;
		}
	}

	@Watch("sentiment")
	handleSentimentChange() {
		this.featureHighlight = this.sentiment === "brand";
	}

	@Watch("anchor")
	handleAnchorChange() {
		if (this.anchor && typeof this.anchor === "string") {
			const root = this.host.getRootNode() as Document | ShadowRoot;
			this.anchorRef = root.querySelector(this.anchor);
		} else if (
			this.anchor instanceof HTMLElement ||
			this.anchor instanceof SVGElement
		) {
			this.anchorRef = this.anchor;
		}
		if (this.anchorRef) {
			this.bindEventsToAnchor();
		}
	}

	/** Shows the popover. */
	@Method()
	async show() {
		if (this.open) {
			return undefined;
		}

		this.open = true;
		this.hbrAfterShow.emit();
	}

	/** Hides the popover */
	@Method()
	async hide() {
		if (this.hasTrigger("hover") && this.cancelHide) {
			return undefined;
		}
		if (!this.open) {
			return undefined;
		}

		this.open = false;
		this.hbrAfterHide.emit();
	}

	private handleBlur = () => {
		if (this.hasTrigger("focus")) {
			this.open = false;
		}
	};

	private handleClick = () => {
		if (this.featureHighlight) return;
		if (this.hasTrigger("click")) {
			this.open = !this.open;
		}
	};

	private handleFocus = () => {
		if (this.hasTrigger("focus")) {
			this.open = true;
		}
	};

	private handleKeyDown = (event: KeyboardEvent) => {
		if (this.featureHighlight) return; //only close when a user explicitly dismisses it using the buttons inside the popover.
		// Pressing escape when the target element has focus should dismiss the popover
		if (this.open && event.key === "Escape") {
			event.stopPropagation();
			this.open = false;
		}
	};

	private handleMouseOver = () => {
		if (this.hasTrigger("hover")) {
			const delay = parseDuration(
				getComputedStyle(this.host).getPropertyValue("--hide-delay"),
			);
			clearTimeout(this.hoverTimeout);
			this.hoverTimeout = window.setTimeout(() => this.show(), delay);
		}
	};

	private handleMouseOut = () => {
		if (this.hasTrigger("hover")) {
			const delay = parseDuration(
				getComputedStyle(this.host).getPropertyValue("--show-delay"),
			);
			clearTimeout(this.hoverTimeout);
			this.hoverTimeout = window.setTimeout(() => this.hide(), delay);
		}
	};

	private handleArrowMouseLeave = () => {
		this.cancelHide = false;
		this.handleMouseOut();
	};

	private handleArrowMouseEnter = () => {
		this.cancelHide = true;
	};

	private hasTrigger(triggerType: string) {
		const triggers = this.trigger.split(" ");
		return triggers.includes(triggerType);
	}

	private isTargetWithin(e) {
		return (
			e.target.closest("hbr-popover") === this.host ||
			e.target.closest(".hbr-css-popover__anchor") === this.anchorRef ||
			e.target === this.anchorRef
		);
	}

	private handleBodyClick(e) {
		if (this.featureHighlight) return; //only close when a user explicitly dismisses it using the buttons inside the popover.
		if (this.isTargetWithin(e)) return;
		if (this.trigger === "manual") return;
		const hbrDismiss = this.hbrDismiss.emit();
		if (!hbrDismiss.defaultPrevented) {
			this.hide();
		}
	}

	private bindEventsToAnchor() {
		this.anchorRef.addEventListener("blur", this.handleBlur, true);
		this.anchorRef.addEventListener("focus", this.handleFocus, true);
		this.anchorRef.addEventListener("click", this.handleClick);
		this.anchorRef.addEventListener("keydown", this.handleKeyDown);
		this.anchorRef.addEventListener("mouseover", this.handleMouseOver);
		this.anchorRef.addEventListener("mouseout", this.handleMouseOut);
	}

	connectedCallback() {
		this.handleBodyClick = this.handleBodyClick.bind(this);
		this.handleAnchorChange = this.handleAnchorChange.bind(this);
		this.handleSentimentChange();
	}

	componentDidLoad() {
		this.handleAnchorChange();
		if (this.popupContentRef) this.popupContentRef.hidden = !this.open;

		// If the popover is visible on init, update its position
		if (this.open) {
			this.handleOpenChange();
			this.popupRef.active = true;
			this.popupRef?.reposition();
		}
	}

	render() {
		const anchor = this.anchorRef || this.anchor;
		return (
			<Host>
				<hbr-popup
					part="base"
					exportparts="arrow:base__arrow,popup:base__popup"
					ref={(el) => {
						this.popupRef = el;
					}}
					anchor={anchor}
					class={{
						popover: true,
						"popover--open": this.open,
						"popover--width-expand": this.widthExpand,
						[`popover--${this.variant}`]: true,
						...(this.size ? { [`popover--${this.size}`]: true } : null),
						...(this.sentiment
							? { [`popover--${this.sentiment}`]: true }
							: null),
					}}
					placement={this.placement}
					distance={this.distance}
					skidding={this.skidding}
					strategy={this.enablePopover || this.hoist ? "fixed" : "absolute"}
					enablePopover={this.enablePopover}
					flip
					shift
					arrow
					arrowSize={8}
					onHbr-arrow-mouseleave={this.handleArrowMouseLeave}
					onHbr-arrow-mouseenter={this.handleArrowMouseEnter}
				>
					{!this.anchor ? (
						<div
							slot="anchor"
							class="hbr-css-popover__anchor"
							aria-describedby="popover"
							ref={(el) => {
								this.anchorRef = el as HTMLDivElement;
							}}
						>
							<slot />
						</div>
					) : null}
					<div
						part="body"
						class="popover__body"
						aria-live={this.open ? "polite" : "off"}
						onMouseLeave={() => {
							this.cancelHide = false;
							this.handleMouseOut();
						}}
						onMouseEnter={() => {
							this.cancelHide = true;
						}}
						ref={(el) => {
							this.popupContentRef = el as HTMLDivElement;
						}}
					>
						<slot name="content">{this.content}</slot>
					</div>
				</hbr-popup>
			</Host>
		);
	}
}
