import { Component, Host, Prop, h } from "@stencil/core";
import { illustrationInfo } from "../../../icons/index";

/**
 * @since 1.1.10
 * @status experimental
 *
 * @slot image
 * @slot heading
 * @slot body
 * @slot footer
 * @part image - hero image of the illustration
 * @part content - heading, body and footer parts of the illustration
 *
 */

@Component({
	tag: "hbr-illustration",
	styleUrl: "illustration.scss",
	shadow: true,
})
export class Illustration {
	/** Name of icon used as illustration */
	@Prop({ reflect: true }) name;

	/** Asset used as icon for non autoloading components */
	@Prop() asset: string | (() => string);

	/** Size of the illustration */
	@Prop() size: "large" | "medium" | "small" = "large";

	/** Width of the illustrated icon - deprecated*/
	@Prop() width: string;

	/** Height of the illustrated icon - deprecated */
	@Prop() height: string;

	/** Sentiment of the illustrated icon */
	@Prop({ reflect: true }) sentiment:
		| "interact"
		| "success"
		| "neutral"
		| "info"
		| "warning"
		| "danger" = "info";

	/** Alignment column or row */
	@Prop({ reflect: true }) direction: "row" | "column" = "column";

	/** Retain static colors hardcoded in the svg file of the icon instead of replacing them with css properties by default */
	@Prop({ reflect: true }) staticColors = false;

	render() {
		const {
			name,
			asset,
			size,
			width,
			height,
			sentiment,
			direction,
			staticColors,
		} = this;
		const iconProps: {
			name?: string;
			asset?: string | (() => string);
		} = {};
		if (name) {
			iconProps.name = name;
		} else {
			iconProps.asset = asset ? asset : illustrationInfo;
		}

		return (
			<Host>
				<div
					class={{
						illustration: true,
						[`illustration--${size}`]: true,
						[`illustration--${direction}`]: true,
					}}
				>
					<div class="image" part="image">
						<slot name="image">
							<hbr-icon
								sentiment={sentiment}
								size={size}
								width={width}
								height={height}
								class="static-icon"
								staticColors={staticColors}
								{...iconProps}
							/>
						</slot>
					</div>
					<div class="content" part="content">
						<slot name="heading" />
						<slot name="body" />
						<slot />
						<slot name="footer" />
					</div>
				</div>
			</Host>
		);
	}
}
